import assert from 'node:assert/strict'
import { chromium } from '/home/vercel-sandbox/.npm/_npx/420ff84f11983ee5/node_modules/playwright/index.mjs'

const browser = await chromium.launch({ headless: true, args: ['--no-sandbox'] })
const context = await browser.newContext({ viewport: { width: 1280, height: 900 } })
await context.addInitScript(() => {
  window.transitionRecords = []
  const original = document.startViewTransition.bind(document)
  document.startViewTransition = (...args) => {
    const record = {}
    window.transitionRecords.push(record)
    const transition = original(...args)
    transition.ready.then(() => {
      record.types = [...transition.types]
      record.animations = document.getAnimations().map(animation => ({
        name: animation.animationName,
        pseudo: animation.effect?.pseudoElement,
        timing: animation.effect?.getTiming(),
        frames: animation.effect?.getKeyframes(),
      }))
    }, error => { record.error = String(error) })
    return transition
  }
})
const page = await context.newPage()
const errors = []
page.on('pageerror', error => errors.push(error.message))
try {
  await page.goto('http://localhost:3000/')
  await page.waitForLoadState('networkidle')
  await page.getByRole('link', { name: 'Classic Sneakers "'$89'"' }).click()
  await page.getByRole('heading', { name: 'Classic Sneakers' }).waitFor()
  await page.waitForFunction(() => window.transitionRecords.some(r => r.types?.includes('nav-forward')))
  const forward = await page.evaluate(() => window.transitionRecords)
  console.log('FORWARD', JSON.stringify(forward))
  await page.waitForFunction(() => document.getAnimations().length === 0)
  await page.getByRole('link', { name: 'Back to products' }).click()
  await page.getByRole('heading', { name: 'Products', exact: true }).waitFor()
  await page.waitForFunction(() => window.transitionRecords.some(r => r.types?.includes('nav-back')))
  console.log('BACK', JSON.stringify(await page.evaluate(() => window.transitionRecords.slice(forward.length))))
  assert.deepEqual(errors, [])
} finally {
  await browser.close()
}
EOF
